#include "architecture/wall_authoring.h"
#include <iostream>
#include <stdexcept>
using namespace kalara;using namespace architecture;using namespace geometry;using namespace runtime;
namespace {int checks=0;void check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}Project fixture(){Project p(EntityId("opening-project"));p.title="Openings";EntityHeader building{EntityId("building"),EntityType::building,p.id,{},0,0},floor{EntityId("floor"),EntityType::floor,building.id,{},0,0},layer{EntityId("walls"),EntityType::layer,p.id,{},0,0};p.entities.emplace(building.id,Building{building,"Building",{floor.id}});p.entities.emplace(floor.id,Floor{floor,"Ground",0,{},{}});p.entities.emplace(layer.id,Layer{layer,"Walls"});return p;}EntityId one(const Project& project,EntityType type){for(const auto& [id,entity]:project.entities)if(header(entity).type==type)return id;throw std::runtime_error("entity missing");}std::vector<EntityId> all(const Project& project,EntityType type){std::vector<EntityId> result;for(const auto& [id,entity]:project.entities)if(header(entity).type==type)result.push_back(id);return result;}bool ok(const CommitResult& result){return std::holds_alternative<CommitSuccess>(result);}}
int main(){try{ProjectStore store(fixture());CommandService commands(store);WallAuthoring author(store,commands);check(ok(author.addSegment(EntityId("floor"),EntityId("walls"),{{0,0},{}},{{6000,0},{}})),"host wall created");auto wallId=one(*store.snapshot(),EntityType::wall);OpeningSpec door;door.width=Length(900);door.hinge=HingeEnd::start;door.swing=SwingSide::left;check(ok(author.placeOpening(wallId,Length(2000),door)),"door placement");auto openingId=one(*store.snapshot(),EntityType::opening);check(!ok(author.placeOpening(wallId,Length(2200),door)),"overlap rejected");check(!ok(author.placeOpening(wallId,Length(5800),door)),"overrun rejected");auto beforeReverse=store.snapshot();check(ok(author.reverseWall(wallId)),"wall reversal");auto reversed=std::get<Opening>(*store.snapshot()->find(openingId));check(reversed.centerOffset.mm==4000&&reversed.hinge==HingeEnd::end&&reversed.swing==SwingSide::right,"reversal preserves world semantics");check(ok(commands.undo())&&semanticContentEqual(*beforeReverse,*store.snapshot()),"reversal undo exact");check(!ok(author.splitWall(wallId,Length(2000))),"split through opening rejected");auto beforeSplit=store.snapshot();check(ok(author.splitWall(wallId,Length(1000))),"split before opening");auto afterSplit=store.snapshot();auto remapped=std::get<Opening>(*afterSplit->find(openingId));check(remapped.hostWallId!=wallId&&remapped.centerOffset.mm==1000,"opening remapped to end segment");check(all(*afterSplit,EntityType::wall).size()==2&&all(*afterSplit,EntityType::junction).size()==3,"split topology created");auto newWall=remapped.hostWallId;check(ok(commands.undo())&&semanticContentEqual(*beforeSplit,*store.snapshot()),"split undo restores host and IDs");check(ok(author.splitWall(wallId,Length(1000))),"split repeated");remapped=std::get<Opening>(*store.snapshot()->find(openingId));newWall=remapped.hostWallId;check(ok(author.mergeWalls(wallId,newWall)),"compatible merge");auto merged=store.snapshot();auto restored=std::get<Opening>(*merged->find(openingId));check(restored.hostWallId==wallId&&restored.centerOffset.mm==2000,"merge restores host interval");check(all(*merged,EntityType::wall).size()==1&&all(*merged,EntityType::junction).size()==2,"merge removes redundant topology");check(!ok(author.editOpening(openingId,Length(100),Length(900))),"width grip overrun rejected");check(ok(author.editOpening(openingId,Length(2500),Length(1200))),"along-wall move and width edit");check(ok(author.flipOpening(openingId,true,false))&&std::get<Opening>(*store.snapshot()->find(openingId)).hinge==HingeEnd::end,"explicit hinge flip");check(!ok(author.deleteWall(wallId,false)),"host delete requires dependency expansion");auto beforeDelete=store.snapshot();check(ok(author.deleteWall(wallId,true)),"host and opening deleted atomically");check(!store.snapshot()->find(wallId)&&!store.snapshot()->find(openingId),"dependency deletion complete");check(ok(commands.undo())&&semanticContentEqual(*beforeDelete,*store.snapshot()),"dependency deletion undo restores all");std::cout<<"topology-opening-v1: "<<checks<<" checks PASS; split/remap/reject, merge, reverse, fit, dependency undo\n";return 0;}catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<'\n';return 1;}}
